<?php
require __DIR__.'/bootstrap.php';
try{$count=(int)admin_db()->query('SELECT COUNT(*) FROM admin_users')->fetchColumn();}catch(Throwable $e){http_response_code(503);exit('Admin setup needs the database configured and database/gallery-admin.sql imported.');}
if(!empty($_SESSION['admin_id'])){header('Location: dashboard.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 admin_verify_csrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');
 if(!$email||strlen($password)<12)$error='Enter a valid email and a password with at least 12 characters.';
 else try{$pdo=admin_db();if($count===0){$stmt=$pdo->prepare('INSERT INTO admin_users(email,password_hash) VALUES(?,?)');$stmt->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['admin_id']=(int)$pdo->lastInsertId();$_SESSION['admin_email']=$email;session_regenerate_id(true);header('Location: dashboard.php');exit;}else{$stmt=$pdo->prepare('SELECT id,email,password_hash FROM admin_users WHERE email=? LIMIT 1');$stmt->execute([$email]);$user=$stmt->fetch();if($user&&password_verify($password,$user['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$user['id'];$_SESSION['admin_email']=$user['email'];header('Location: dashboard.php');exit;}$error='Email or password is incorrect.';}}catch(Throwable $e){error_log('Wintrip admin login: '.$e->getMessage());$error='Unable to sign in right now. Check the database setup.';}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login | Wintrip Safaris</title><link rel="stylesheet" href="../assets/css/admin.css?v=1"></head><body class="admin-login"><main class="login-card"><a class="admin-brand" href="../index.html">WINTRIP <span>SAFARIS</span></a><p class="admin-eyebrow"><?= $count===0?'FIRST-TIME SETUP':'PRIVATE ADMIN AREA' ?></p><h1><?= $count===0?'Create the administrator account':'Welcome back' ?></h1><p><?= $count===0?'This one-time setup creates the first administrator. After this account is created, public registration is disabled.':'Sign in to manage website photos and gallery content.' ?></p><?php if($error): ?><div class="admin-error"><?=admin_h($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><label>Administrator email<input type="email" name="email" required autocomplete="username" placeholder="you@wintripsafaris.com"></label><label>Password<input type="password" name="password" required minlength="12" autocomplete="<?= $count===0?'new-password':'current-password' ?>" placeholder="At least 12 characters"></label><button class="admin-button" type="submit"><?= $count===0?'Create admin account':'Sign in securely' ?></button></form><a class="back-site" href="../index.html">← Return to public website</a><small>Private Wintrip Safaris website management</small></main></body></html>